<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getPage, post, put, type PageResult } from '@/api/resources'
import { http, problemMessage } from '@/api/http'
import ProductionHint from '@/components/ProductionHint.vue'
import SectionState from '@/components/SectionState.vue'
import { formatDate } from '@/utils/format'

interface Park { name: string; description: string; openHours: string; phone: string; longitude: number; latitude: number; zones: { id: string; name: string }[] }
interface ImportBatch { id: string; type: string; layerKind: string; status: string; rows?: number; errors?: string[]; createdAt?: string; fileName?: string }
const park = reactive<Park>({ name: '', description: '', openHours: '', phone: '', longitude: 121.43, latitude: 31.19, zones: [] }); const imports = ref<PageResult<ImportBatch>>({ items: [], total: 0, page: 1, pageSize: 20 }); const loading = ref(true); const error = ref(''); const saving = ref(false); const importDialog = ref(false); const file = ref<File>(); const importForm = reactive({ type: 'GeoJSON', layerKind: 'Boundary', bounds: '' }); const preview = ref<ImportBatch>(); const confirming = ref(false)
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const [parkData, importsData] = await Promise.all([http.get<Park>('/platform/park'), getPage<ImportBatch>('/platform/imports')]); Object.assign(park, parkData.data); imports.value = importsData } catch (e) { error.value = problemMessage(e) } finally { loading.value = false } }
async function savePark(): Promise<void> { saving.value = true; try { await put('/platform/park', park); ElMessage.success('公园基础信息已保存。') } catch (e) { ElMessage.error(problemMessage(e)) } finally { saving.value = false } }
async function previewImport(): Promise<void> { if (!file.value) return ElMessage.warning('请先选择导入文件。'); const body = new FormData(); body.append('file', file.value); body.append('type', importForm.type); body.append('layerKind', importForm.layerKind); if (importForm.bounds) body.append('bounds', importForm.bounds); try { preview.value = await post<ImportBatch>('/platform/imports/preview', body) } catch (e) { ElMessage.error(problemMessage(e)) } }
async function confirmImport(): Promise<void> { if (!preview.value?.id) return; confirming.value = true; try { await post(`/platform/imports/${preview.value.id}/confirm`); ElMessage.success('导入批次已确认。'); importDialog.value = false; preview.value = undefined; await load() } catch (e) { ElMessage.error(problemMessage(e)) } finally { confirming.value = false } }
onMounted(() => { void load() })
</script>
<template><div class="page"><div class="page-heading"><div><h1>智慧公园数据平台</h1><p>维护单公园基础底板、导入批次与演示资源台账。</p></div><el-button type="primary" @click="importDialog = true">导入空间或元素数据</el-button></div><SectionState :loading="loading" :error="error" @retry="load"><div class="grid-2"><section class="surface section-card"><div class="data-title">公园基础信息</div><el-form class="park-form" label-position="top"><el-form-item label="公园名称"><el-input v-model="park.name" /></el-form-item><el-form-item label="公园简介"><el-input v-model="park.description" type="textarea" :rows="3" /></el-form-item><div class="form-row"><el-form-item label="开放时间"><el-input v-model="park.openHours" /></el-form-item><el-form-item label="服务电话"><el-input v-model="park.phone" /></el-form-item></div><div class="form-row"><el-form-item label="中心经度"><el-input-number v-model="park.longitude" :precision="6" /></el-form-item><el-form-item label="中心纬度"><el-input-number v-model="park.latitude" :precision="6" /></el-form-item></div><el-form-item label="区域"><el-tag v-for="zone in park.zones" :key="zone.id" class="zone-tag">{{ zone.name }}</el-tag><span v-if="!park.zones.length" class="muted">暂无区域数据</span></el-form-item><el-button type="primary" :loading="saving" @click="savePark">保存基础信息</el-button></el-form></section><section class="surface section-card"><div class="data-title">导入要求</div><div class="requirement"><b>GeoJSON / DLG</b><p>仅接受 WGS84 标准 FeatureCollection，坐标顺序为经度、纬度。预览校验后才可确认写入。</p></div><div class="requirement"><b>元素 CSV</b><p>资产编码唯一，坐标、类型及外键错误会在预览中逐项返回。</p></div><div class="requirement"><b>DOM 影像</b><p>仅显示已配准 PNG/JPEG，需手工提供西南、东北经纬度范围。</p></div><ProductionHint topic="gis" /><ProductionHint topic="video" compact /><ProductionHint topic="deployment" compact /></section></div><section class="surface imports"><div class="panel-title"><div><b>导入批次台账</b><span>操作人、原文件与错误摘要由服务端记录</span></div></div><el-table :data="imports.items" empty-text="暂无导入批次"><el-table-column prop="fileName" label="文件" min-width="170" /><el-table-column prop="type" label="类型" width="110" /><el-table-column prop="layerKind" label="图层/类别" width="120" /><el-table-column prop="rows" label="有效行/要素" width="120" /><el-table-column prop="status" label="状态" width="120" /><el-table-column label="时间" width="180"><template #default="scope">{{ formatDate(scope.row.createdAt) }}</template></el-table-column><el-table-column label="错误摘要" min-width="200"><template #default="scope">{{ scope.row.errors?.join('；') || '—' }}</template></el-table-column></el-table></section></SectionState><el-dialog v-model="importDialog" title="预览并确认导入" width="620px" :close-on-click-modal="false"><el-form label-position="top"><div class="form-row"><el-form-item label="文件类型"><el-select v-model="importForm.type"><el-option label="GeoJSON" value="GeoJSON" /><el-option label="CSV" value="CSV" /><el-option label="DOM 影像" value="DOM" /></el-select></el-form-item><el-form-item label="图层类型"><el-select v-model="importForm.layerKind"><el-option label="边界" value="Boundary" /><el-option label="园路" value="Road" /><el-option label="兴趣点" value="POI" /></el-select></el-form-item></div><el-form-item v-if="importForm.type === 'DOM'" label="范围 JSON（[西南,东北] 经纬度）"><el-input v-model="importForm.bounds" placeholder='[[121.42,31.18],[121.44,31.20]]' /></el-form-item><el-form-item label="导入文件"><el-upload :auto-upload="false" :limit="1" :on-change="item => file = item.raw" :on-remove="() => file = undefined"><el-button>选择文件</el-button><template #tip><div class="el-upload__tip">文件先校验预览，不会直接入库。</div></template></el-upload></el-form-item></el-form><el-button type="primary" @click="previewImport">开始预览校验</el-button><div v-if="preview" class="preview-result"><b>预览结果：{{ preview.rows ?? 0 }} 条有效数据</b><p v-if="preview.errors?.length">错误：{{ preview.errors.join('；') }}</p><p v-else>校验通过后可确认导入。</p></div><template #footer><el-button @click="importDialog = false">取消</el-button><el-button type="primary" :disabled="!preview || !!preview.errors?.length" :loading="confirming" @click="confirmImport">确认写入</el-button></template></el-dialog></div></template>
<style scoped>.section-card { padding:20px; }.park-form { margin-top:18px; }.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }.zone-tag { margin-right:7px; }.requirement { padding:12px 0; border-bottom:1px solid #edf1ef; }.requirement b { color:#2c574e; font-size:13px; }.requirement p { margin:6px 0 0; color:#71827d; font-size:12px; line-height:1.65; }.imports { margin-top:18px; padding:18px; }.panel-title { margin-bottom:14px; }.panel-title b,.panel-title span { display:block; }.panel-title span { margin-top:4px; color:#73847e; font-size:12px; }.preview-result { margin-top:18px; padding:13px; border-radius:8px; background:#f1f7f4; color:#49665e; font-size:13px; }.preview-result p { margin:6px 0 0; }</style>
